1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const ALIKE_ITEMS_BLOCK = { size: 3, basePremium: 60 };
68	
69	const basePremiumForItemType = (type: string, count: number): number =>
70	  count === ALIKE_ITEMS_BLOCK.size
71	    ? ALIKE_ITEMS_BLOCK.basePremium
72	    : count * BASE_PREMIUMS[type];
73	
74	const countByType = (items: Item[]): Map<string, number> =>
75	  items.reduce(
76	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
77	    new Map<string, number>(),
78	  );
79	
80	const policyBasePremium = (items: Item[]): number =>
81	  [...countByType(items)].reduce(
82	    (total, [type, count]) => total + basePremiumForItemType(type, count),
83	    0,
84	  );
85	
86	const CURSE_SURCHARGE_RATE = 0.5;
87	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
88	const HIGH_ENCHANTMENT_LEVEL = 5;
89	
90	const isHighlyEnchanted = (item: Item): boolean =>
91	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
92	
93	interface RiskFactor {
94	  applies: (item: Item) => boolean;
95	  rate: number;
96	}
97	
98	const RISK_FACTORS: RiskFactor[] = [
99	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
100	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
101	];
102	
103	const itemRiskSurcharge = (item: Item): number =>
104	  RISK_FACTORS.reduce(
105	    (total, { applies, rate }) =>
106	      applies(item) ? total + BASE_PREMIUMS[item.type] * rate : total,
107	    0,
108	  );
109	
110	const totalRiskSurcharges = (items: Item[]): number =>
111	  items.reduce((total, item) => total + itemRiskSurcharge(item), 0);
112	
113	const LOYALTY_DISCOUNT_RATE = -0.2;
114	const LOYALTY_YEARS = 2;
115	
116	const isLoyal = (customer: Customer): boolean =>
117	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
118	
119	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
120	
121	/** A quote in the context of the customer's history with the MHPCO. */
122	interface Contract {
123	  customer: Customer;
124	  /** Zero-based ordinal of this quote among the customer's quotes. */
125	  ordinal: number;
126	}
127	
128	const isFollowUpContract = (contract: Contract): boolean =>
129	  contract.ordinal > 0;
130	
131	/**
132	 * Policy-wide modifiers are charged on the policy base premium, unlike the
133	 * item-specific RISK_FACTORS which are charged on each affected item's own
134	 * base premium. Rates are signed: negative is a discount.
135	 */
136	interface PolicyFactor {
137	  applies: (contract: Contract) => boolean;
138	  rate: number;
139	}
140	
141	const POLICY_FACTORS: PolicyFactor[] = [
142	  {
143	    applies: ({ customer }) => isLoyal(customer),
144	    rate: LOYALTY_DISCOUNT_RATE,
145	  },
146	  { applies: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
147	  {
148	    applies: isFollowUpContract,
149	    rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
150	  },
151	];
152	
153	const totalPolicyAdjustments = (
154	  policyBase: number,
155	  contract: Contract,
156	): number =>
157	  POLICY_FACTORS.reduce(
158	    (total, { applies, rate }) =>
159	      applies(contract) ? total + policyBase * rate : total,
160	    0,
161	  );
162	
163	const quotePremium = (items: Item[], contract: Contract): number => {
164	  const policyBase = policyBasePremium(items);
165	  return Math.ceil(
166	    policyBase +
167	      totalRiskSurcharges(items) +
168	      totalPolicyAdjustments(policyBase, contract) +
169	      PROCESSING_FEE,
170	  );
171	};
172	
173	const INSURANCE_VALUES: Record<string, number> = {
174	  sword: 1000,
175	  amulet: 600,
176	  staff: 800,
177	  potion: 400,
178	  rune: 250,
179	  moonstone: 250,
180	};
181	
182	const DEDUCTIBLE_PER_DAMAGE = 100;
183	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
184	
185	const insuranceSum = (items: Item[]): number =>
186	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
187	
188	const payoutCap = (items: Item[]): number =>
189	  insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
190	
191	const REIMBURSED_ENCHANTMENT_LEVEL = 8;
192	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
193	
194	/**
195	 * The share of a damage amount the MHPCO reimburses, before the deductible.
196	 * Damage to a heavily enchanted item is reimbursed at half.
197	 */
198	const reimbursementRate = (item: Item): number =>
199	  (item.enchantment ?? 0) >= REIMBURSED_ENCHANTMENT_LEVEL
200	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
201	    : 1;
202	
203	const damagePayout = (damage: Damage, policyItems: Item[]): number => {
204	  const damagedItem = policyItems.find(
205	    (item) => item.type === damage.itemType,
206	  ) as Item;
207	  return damage.amount * reimbursementRate(damagedItem) - DEDUCTIBLE_PER_DAMAGE;
208	};
209	
210	const claimResult = (step: ClaimStep, policyItems: Item[]): ClaimResult => {
211	  const payout = step.incident.damages.reduce(
212	    (total, damage) => total + damagePayout(damage, policyItems),
213	    0,
214	  );
215	  // Each claim is settled against the policy's full cap: earlier claims against
216	  // the same policy do not yet reduce it.
217	  const remainingCap = payoutCap(policyItems) - payout;
218	  return { payout, remainingCap };
219	};
220	
221	/**
222	 * The items covered by the policy a claim is filed against. A claim's `policy`
223	 * is the index of the quote step that established the policy.
224	 *
225	 * Assumes that step is in fact a quote; no test yet covers a claim pointing at
226	 * a non-quote step, so the assumption is asserted rather than checked.
227	 */
228	const policyItemsFor = (steps: Step[], claim: ClaimStep): Item[] =>
229	  (steps[claim.policy] as QuoteStep).items;
230	
231	const runStep = (
232	  step: Step,
233	  contract: Contract,
234	  steps: Step[],
235	): StepResult => {
236	  if (step.op === "claim") {
237	    return claimResult(step, policyItemsFor(steps, step));
238	  }
239	  return { premium: quotePremium(step.items, contract) };
240	};
241	
242	/** The contract ordinal of a step: how many quotes precede it. */
243	const contractOrdinalOf = (steps: Step[], index: number): number =>
244	  steps.slice(0, index).filter((step) => step.op === "quote").length;
245	
246	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
247	  results: steps.map((step, index) =>
248	    runStep(step, { customer, ordinal: contractOrdinalOf(steps, index) }, steps),
249	  ),
250	});
